import React from 'react';
import { FiCheck, FiMenu } from 'react-icons/fi';

const FilterSidebar = ({ filters, onFilterChange, onSortChange }) => {
  const statusOptions = [
    { label: 'All Status', value: '' },
    { label: 'To Do', value: 'todo' },
    { label: 'In Progress', value: 'in_progress' },
    { label: 'Done', value: 'done' }
  ];

  const priorityOptions = [
    { label: 'All Priorities', value: '' },
    { label: 'Low', value: 'low' },
    { label: 'Medium', value: 'medium' },
    { label: 'High', value: 'high' }
  ];

  const sortOptions = [
    { label: 'Newest First', sortBy: 'created_at', sortOrder: 'desc' },
    { label: 'Oldest First', sortBy: 'created_at', sortOrder: 'asc' },
    { label: 'Title A-Z', sortBy: 'title', sortOrder: 'asc' },
    { label: 'Title Z-A', sortBy: 'title', sortOrder: 'desc' },
    { label: 'Priority High-Low', sortBy: 'priority', sortOrder: 'desc' },
    { label: 'Priority Low-High', sortBy: 'priority', sortOrder: 'asc' },
    { label: 'Due Date Soonest', sortBy: 'due_date', sortOrder: 'asc' },
    { label: 'Due Date Latest', sortBy: 'due_date', sortOrder: 'desc' }
  ];

  return (
    <div className="w-full md:w-64 space-y-4">
      <div className="border-rounded-lg bg-surface/50 p-4 border border-border-color">
        <h3 className="text-lg font-semibold mb-3">Filters</h3>

        <div className="space-y-3">
          <div>
            <label className="block text-sm font-medium mb-1">Status</label>
            <select
              value={filters.status || ''}
              onChange={(e) => {
                const value = e.target.value;
                onFilterChange(prev => ({
                  ...prev,
                  ...(value ? { status: value } : { status: undefined })
                }));
              }}
              className="w-full px-3 py-2 rounded-lg bg-background/50 border border-border-color text-primary-text focus:outline-none focus:ring-2 focus:ring-accent-color focus:border-accent-color"
            >
              {statusOptions.map(option => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-1">Priority</label>
            <select
              value={filters.priority || ''}
              onChange={(e) => {
                const value = e.target.value;
                onFilterChange(prev => ({
                  ...prev,
                  ...(value ? { priority: value } : { priority: undefined })
                ));
              }}
              className="w-full px-3 py-2 rounded-lg bg-background/50 border border-border-color text-primary-text focus:outline-none focus:ring-2 focus:ring-accent-color focus:border-accent-color"
            >
              {priorityOptions.map(option => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-1">Tags</label>
            <input
              type="text"
              placeholder="e.g., work, urgent"
              className="w-full px-3 py-2 rounded-lg bg-background/50 border border-border-color text-primary-text placeholder-secondary-text focus:outline-none focus:ring-2 focus:ring-accent-color focus:border-accent-color"
            />
          </div>
        </div>

        <button
          onClick={() => onFilterChange({})}
          className="w-full px-3 py-2 rounded-lg bg-background/50 border border-border-color text-primary-text text-sm hover:bg-surface/50 focus-ring"
        >
          Clear Filters
        </button>
      </div>

      <div className="border-rounded-lg bg-surface/50 p-4 border border-border-color">
        <h3 className="text-lg font-semibold mb-3">Sort By</h3>

        <div className="space-y-2">
          {sortOptions.map(option => (
            <div key={`${option.sortBy}-${option.sortOrder}`} className="flex items-center p-2 rounded-lg hover:bg-surface/50 transition-colors cursor-pointer" 
                 onClick={() => onSortChange(option.sortBy, option.sortOrder)}
                 className={`${filters.sortBy === option.sortBy && filters.sortOrder === option.sortOrder ? 'bg-accent-color/20' : ''}`}>
              <FiCheck className={`${filters.sortBy === option.sortBy && filters.sortOrder === option.sortOrder ? 'text-accent-color' : 'text-secondary-text'} mr-2 h-4 w-4`} />
              <span className="text-sm text-primary-text">{option.label}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default FilterSidebar;
